import { supabase } from './client'
import type {
  Certification,
  Chapter,
  LearningObjective,
  Question,
} from '@/types/database'

export async function getCertifications(): Promise<Certification[]> {
  const { data, error } = await supabase
    .from('certifications')
    .select('id, name')
    .order('name')

  if (error) throw new Error(error.message)

  return data ?? []
}

export async function getChapters(
  certificationId: number,
): Promise<Chapter[]> {
  const { data, error } = await supabase
    .from('chapters')
    .select('id, certification_id, chapter_number, chapter_name')
    .eq('certification_id', certificationId)
    .order('chapter_number')

  if (error) throw new Error(error.message)

  return data ?? []
}

export async function getLearningObjectives(
  sectionId: number,
): Promise<LearningObjective[]> {
  const { data, error } = await supabase
    .from('learning_objectives')
    .select('id, chapter_id, lo_number, lo_title')
    .eq('section_id', sectionId)
    .order('objective_code')

  if (error) throw new Error(error.message)

  return data ?? []
}

export async function getQuestionsByChapter(
  chapterId: number,
  limit = 20,
): Promise<Question[]> {
  const supabase = getSupabase()

  const { data, error } = await supabase
    .from('questions')
    .select(`
      id,
      learning_objective_id,
      question_text,
      difficulty,
      learning_objectives!inner (
        id,
        chapter_id,
        lo_number,
        lo_title
      ),
      answer_options (
        id,
        question_id,
        option_text
      )
    `)
    .eq('learning_objectives.chapter_id', chapterId)
    .limit(limit)

  if (error) {
    console.error('Questions query failed:', {
      code: error.code,
      message: error.message,
      details: error.details,
      hint: error.hint,
    })

    throw new Error(
      error.message || `Supabase error ${error.code}`,
    )
  }

  return (data ?? []).map((question) => ({
    id: question.id,
    learning_objective_id: question.learning_objective_id,
    question_text: question.question_text,
    difficulty: question.difficulty,
    answer_options: question.answer_options ?? [],
  }))
}

export async function getQuestionsByCertification(
  certificationId: number,
): Promise<Question[]> {
  try {
    // First, get all chapters for this certification
    const { data: chapters, error: chaptersError } = await supabase
      .from('chapters')
      .select('id')
      .eq('certification_id', certificationId)

    if (chaptersError) throw chaptersError
    if (!chapters || chapters.length === 0) return []

    const chapterIds = chapters.map((c) => c.id)

    // Then get all learning objectives for those chapters
    const { data: objectives, error: objectivesError } = await supabase
      .from('learning_objectives')
      .select('id')
      .in('chapter_id', chapterIds)

    if (objectivesError) throw objectivesError
    if (!objectives || objectives.length === 0) return []

    const objectiveIds = objectives.map((o) => o.id)

    // Finally, get all questions for those objectives
    const { data, error } = await supabase
      .from('questions')
      .select(`
        id,
        learning_objective_id,
        question_text,
        difficulty,
        answer_options (
          id,
          question_id,
          option_text,
          is_correct,
          display_order
        )
      `)
      .in('learning_objective_id', objectiveIds)
      .eq('available', true)

    if (error) throw error

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    return (data ?? []).map((question: any) => ({
      id: question.id,
      learning_objective_id: question.learning_objective_id,
      question_text: question.question_text,
      difficulty: question.difficulty,
      answer_options: question.answer_options || []
    }))
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Unknown error'
    throw new Error(`Failed to load questions: ${message}`)
  }
}